* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background-color: #2d1b2e;
  color: #f0e6d2;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.game-board {
  background-color: #3e2a3f;
  border-radius: 24px;
  padding: 32px 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 8px 0 #1e1220, 0 12px 24px rgba(0, 0, 0, 0.5);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 24px;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: 1px;
  color: #ffd166;
  text-shadow: 2px 2px 0 #1e1220;
}

.pet-container {
  width: 160px;
  height: 160px;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #5a3e5b;
  border-radius: 50%;
  border: 4px solid #1e1220;
  box-shadow: inset 0 -6px 0 #1e1220, 0 6px 0 #1e1220;
}

.pet {
  position: relative;
  width: 100px;
  height: 100px;
  transition: transform 0.2s;
}

.pet-body {
  position: absolute;
  inset: 0;
  background-color: #ffd166;
  border-radius: 20px;
  border: 4px solid #1e1220;
  box-shadow: inset -6px -6px 0 #e6b800, 0 6px 0 #1e1220;
}

.pet-eye {
  position: absolute;
  width: 16px;
  height: 16px;
  background-color: #1e1220;
  border-radius: 50%;
  top: 30px;
}

.pet-eye.left {
  left: 20px;
}

.pet-eye.right {
  right: 20px;
}

.pet-mouth {
  position: absolute;
  width: 30px;
  height: 12px;
  border-bottom: 4px solid #1e1220;
  border-radius: 0 0 50% 50%;
  bottom: 25px;
  left: 50%;
  transform: translateX(-50%);
  transition: all 0.2s;
}

.pet.sad .pet-mouth {
  border-bottom: none;
  border-top: 4px solid #1e1220;
  border-radius: 50% 50% 0 0;
  bottom: 20px;
}

.pet.sleeping .pet-eye {
  height: 4px;
  border-radius: 0;
  top: 38px;
}

.pet.sleeping .pet-mouth {
  width: 16px;
  height: 8px;
  border-bottom: 4px solid #1e1220;
  border-radius: 0 0 50% 50%;
  bottom: 30px;
}

.mood {
  font-size: 1.25rem;
  font-weight: 600;
  color: #ffd166;
  min-height: 1.5em;
  text-align: center;
}

.stats {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.stat {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.stat-label {
  font-size: 1rem;
  font-weight: 600;
  color: #f0e6d2;
}

.bar-container {
  width: 100%;
  height: 20px;
  background-color: #1e1220;
  border-radius: 10px;
  overflow: hidden;
  border: 2px solid #1e1220;
}

.bar {
  height: 100%;
  width: 100%;
  border-radius: 8px;
  transition: width 0.3s ease;
}

.bar.hunger {
  background-color: #ef476f;
}

.bar.happiness {
  background-color: #06d6a0;
}

.bar.energy {
  background-color: #118ab2;
}

.controls {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: center;
  width: 100%;
}

button {
  font-family: inherit;
  font-size: 1.125rem;
  font-weight: 700;
  padding: 12px 24px;
  border: none;
  border-radius: 12px;
  cursor: pointer;
  background-color: #ffd166;
  color: #1e1220;
  box-shadow: 0 4px 0 #1e1220;
  transition: transform 0.1s, box-shadow 0.1s, background-color 0.2s;
  flex: 1 1 auto;
  min-width: 100px;
}

button:hover {
  background-color: #ffe08a;
}

button:focus-visible {
  outline: 3px solid #06d6a0;
  outline-offset: 2px;
}

button:active {
  transform: translateY(4px);
  box-shadow: 0 0 0 #1e1220;
}

@media (max-width: 400px) {
  .game-board {
    padding: 24px 16px;
  }
  button {
    padding: 10px 16px;
    font-size: 1rem;
    min-width: 80px;
  }
}

const state = {
  hunger: 80,
  happiness: 80,
  energy: 80,
};

const petEl = document.getElementById('pet');
const moodEl = document.getElementById('mood');
const hungerBar = document.getElementById('hungerBar');
const happinessBar = document.getElementById('happinessBar');
const energyBar = document.getElementById('energyBar');

const feedBtn = document.getElementById('feedBtn');
const playBtn = document.getElementById('playBtn');
const sleepBtn = document.getElementById('sleepBtn');

function clamp(value) {
  return Math.max(0, Math.min(100, value));
}

function updateUI() {
  hungerBar.style.width = state.hunger + '%';
  happinessBar.style.width = state.happiness + '%';
  energyBar.style.width = state.energy + '%';

  petEl.classList.remove('sad', 'sleeping');

  let mood = 'Happy';
  if (state.hunger < 30 || state.happiness < 30 || state.energy < 30) {
    mood = 'Sad';
    petEl.classList.add('sad');
  } else if (state.energy < 20) {
    mood = 'Sleepy';
    petEl.classList.add('sleeping');
  } else if (state.hunger > 80 && state.happiness > 80 && state.energy > 80) {
    mood = 'Ecstatic';
  } else if (state.hunger < 50 || state.happiness < 50 || state.energy < 50) {
    mood = 'Okay';
  }

  moodEl.textContent = mood;
}

function decay() {
  state.hunger = clamp(state.hunger - 2);
  state.happiness = clamp(state.happiness - 1);
  state.energy = clamp(state.energy - 1);
  updateUI();
}

feedBtn.addEventListener('click', () => {
  state.hunger = clamp(state.hunger + 20);
  state.happiness = clamp(state.happiness + 5);
  updateUI();
});

playBtn.addEventListener('click', () => {
  state.happiness = clamp(state.happiness + 20);
  state.energy = clamp(state.energy - 10);
  state.hunger = clamp(state.hunger - 5);
  updateUI();
});

sleepBtn.addEventListener('click', () => {
  state.energy = clamp(state.energy + 30);
  state.happiness = clamp(state.happiness - 5);
  state.hunger = clamp(state.hunger - 5);
  updateUI();
});

setInterval(decay, 5000);

updateUI();
